t = input()
t = int(t)
while t:
	t = t - 1
	n_m = input()
	n_m = n_m.split(' ')
	n = int(n_m[0])
	m = int(n_m[1])
	matrix = []
	for i in range(n):
		row = input()
		row = list(row)
		row = list(map(int, row))
		matrix.append(row)
	v_rows = [False] * n
	v_cols = [False] * m
	ans = [[-1 for j in range(m)] for i in range(n)]
	exist = False
	for i in range(n):
		for j in range(m):
			if matrix[i][j] == 1:
				exist = True
				v_rows[i] = True
				v_cols[j] = True
	for i in range(n):
		for j in range(m):
			if matrix[i][j] == 1:
				ans[i][j] = 0
			elif v_rows[i] == True:
				ans[i][j] = 1
			elif v_cols[j] == True:
				ans[i][j] = 1
			elif exist:
				ans[i][j] = 2
			else:
				ans[i][j] = -1
	for i in range(n):
		col_j = ''
		for j in range(m):
			col_j = col_j + str(ans[i][j]) + ' '
		print(col_j)
